// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the 'from' address and the length of _tos via an array size represented by uint8
    function testFuzz_property(address from, uint8 tosLen) public {
        // keep tosLen reasonably bounded but allow zero to trigger the mutant behavior
        uint256 len = uint256(tosLen);

        // build arrays according to len
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(this); // call a simple contract/address that will accept the low-level call
            vals[i] = 1;
        }

        // Call transfer and capture whether it completes (does not revert) and its returned boolean if any
        bool ok;
        // We must call through try/catch to observe revert vs non-revert
        try c.transfer(from, address(this), tos, vals) returns (bool ret) {
            ok = ret; // if call returns, record returned value
        } catch {
            // if it reverts, set ok to false sentinel different from true return
            // Use false to indicate non-successful completion; reference contract reverts when len==0
            ok = false;
        }

        // GENERAL RULE: The reference contract never returns false; it either reverts (for empty tos) or returns true.
        // Therefore assertTrue(ok == true || len == 0 ? ok == false || ok == true : ok == true) is too convoluted.
        // We instead assert the universal property: if the call completed (did not revert) then it returned true.
        // We encoded completion as reaching returns branch (ok==ret). For the case of revert, ok==false via catch;
        // So the property to assert: if the call completed (i.e., len != 0 for reference) then ok must be true.

        // To implement: if len == 0 the reference reverts -> catch path sets ok=false; if len > 0 reference returns true -> ok==true.
        // So the single assertion below captures that for all admissible inputs the reference yields (len==0 => ok==false) OR (len>0 => ok==true).
        // This is equivalent to: ok == (len > 0);

        assertTrue(ok == (len > 0));
    }
}

