pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (actor address), calleeSeed (used to deploy distinct helper), len (length of arrays)
    function testFuzz_property(address from, uint256 calleeSeed, uint256 len) public {
        // keep len in a practical range but wide enough to allow >0
        len = bound(len, 1, 4); // require _tos.length > 0 in C

        // Deploy an adversarial helper that, when its transferFrom selector is called,
        // writes to its own storage slot 0. When called via delegatecall this will
        // instead write slot 0 of the caller (C). Thus the reference (call) should
        // NOT change C's storage, but the mutant (delegatecall) may.
        Adversary adv = new Adversary(calleeSeed);

        // Build tos and values arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(adv);
            vals[i] = uint256(1 + i + (calleeSeed & 0xff));
        }

        // Ensure 'from' has some ether (not strictly needed here, but safe).
        vm.deal(from, 1 ether);

        // Call transfer and observe whether C's public getter for slot0 (a public uint named `transfer` in mutant description)
        // changed. We rely on a public getter `transfer()` existing in the real C; if not, reading address(c).balance
        // would not detect this bug. The problem statement says 'value of state variable transfer differs' so we call
        // the getter transfer() (auto-generated). Use try/catch to capture revert differences if any.

        bool ok;
        try c.transfer(from, address(adv), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct reference implementation (which uses call),
        // invoking transfer must NOT modify C.transfer()'s stored value for any admissible inputs.
        // So assert that the getter equals 0 (the default) after the call. This holds for the ref impl
        // for all inputs, but the delegatecall mutant can write into C's slot 0 and make this non-zero
        // for some inputs — the fuzzer will find such inputs when run against the mutant.
        uint stored = c.transfer();
        assertTrue(stored == 0);
    }
}

// Minimal adversarial helper: when its transferFrom(address,address,uint256) is invoked it writes 1 to storage slot 0.
contract Adversary {
    uint256 public seed;
    constructor(uint256 _seed) { seed = _seed; }

    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) public returns (bool) {
        // write to slot 0
        assembly { sstore(0, 1) }
        return true;
    }
}

