pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address and an array length and a value to be passed to the adversarial callee
    function testFuzz_property(address from, uint8 len, uint256 val) public {
        // keep length within reasonable bounds but wide enough
        uint256 l = uint256(len) % 8; // 0..7
        vm.assume(l > 0); // admissible domain: _tos.length > 0 as required by C

        // deploy an adversarial callee that, when called, will write to its own storage slot 0
        // (which would become C's slot 0 if delegatecall is used)
        BadCallee bad = new BadCallee(val);

        // build arrays of addresses and values
        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; ++i) {
            tos[i] = address(bad);
            vals[i] = val + i; // vary values slightly
        }

        // record a public uint256 getter on C before the call. The contract under test must have
        // a public uint (slot 0) named `transfer` or similar; if not, reading storage via a getter is required
        // Since we cannot assume a getter name, we read address(c).balance as a benign observable that the
        // reference preserves but mutant might change via delegatecall if callee selfdestructs or transfers. 
        // However balance is not affected by delegatecall, so instead we rely on trying the call and observing
        // its success boolean: reference will succeed if callee call returns true, delegatecall may behave differently
        // We'll call and observe whether the call to transfer succeeds (does not revert). The reference calls
        // external contracts, so success depends on callee behavior; the mutant using delegatecall could cause
        // a revert in C context for certain callee bytecode. Thus we assert that the transfer call does not revert
        // for all inputs when callee returns success — the reference preserves that, while mutant may revert for some inputs.

        bool ok;
        try c.transfer(from, address(bad), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any admissible inputs where the external callee's transferFrom returns/does not revert,
        // the reference C.transfer(...) completes (ok == true). The mutant using delegatecall can cause an execution
        // in C's context that reverts for some inputs, making ok == false. We assert that ok is true — the reference
        // satisfies this for all inputs; the mutant will fail for some inputs.
        assertTrue(ok);
    }
}

// adversarial callee: provides a transferFrom selector that returns true
contract BadCallee {
    uint256 public slot0;
    uint256 init;
    constructor(uint256 v) {
        init = v;
        slot0 = 0;
    }
    // matches transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        // write to own storage (slot0) and return true
        slot0 = amount + init;
        return true;
    }
}

