pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address (actor) and a value to have the adversarial callee send to C
    function testFuzz_property(address from, uint256 sendValue) public {
        // keep sendValue reasonable but wide; avoid underflow/overflow nonsense
        sendValue = bound(sendValue, 0, 1 ether);
        // ensure there is at least one recipient
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);

        // deploy adversarial helper that will, when called via transferFrom selector, selfdestruct sending Ether to msg.sender (which under delegatecall would be C)
        Attacker attacker = new Attacker{value: 0}();

        tos[0] = address(attacker);
        vals[0] = 1;

        // fund attacker so it can send/destruct to C if it runs in its own context
        vm.deal(address(attacker), sendValue);
        // record C balance before
        uint256 before = address(c).balance;

        // call transfer; the reference uses call so any selfdestruct in attacker affects attacker balance only, not C
        // we need to call as some sender 'from' (fuzzed). If from is the zero address, it's fine; we just call normally.
        // Use try/catch to observe whether the call succeeded; but the property we assert is about C's balance unchanged.
        try c.transfer(from, address(attacker), tos, vals) {
            // no-op
        } catch {
            // ignore revert; property still must hold for reference
        }

        uint256 after = address(c).balance;

        // The single assertion: for the correct contract, C's balance never increases from this operation for any inputs
        assertTrue(after == before);
    }
}

// Adversarial helper: exposes a transferFrom selector that, when executed, will selfdestruct sending its balance to msg.sender
contract Attacker {
    // allow funding
    receive() external payable {}

    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) public returns (bool) {
        // send entire balance to msg.sender and selfdestruct
        selfdestruct(payable(msg.sender));
        // unreachable
        return true;
    }
}

