pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address for the adversarial callee's owner and an index/amount
    // The fuzzer will vary these to find a case where delegatecall would modify c's storage
    function testFuzz_property(address attacker, uint256 seed) public {
        // Keep attacker nonzero to be a valid externally owned account for deployment roles
        vm.assume(attacker != address(0));

        // Deploy adversarial callee that, when called via transferFrom selector, will write to slot
        // so that delegatecall would mutate C's storage but call would only mutate the callee's own storage.
        Adversary adv = new Adversary();

        // prepare arrays with one entry (transfer requires _tos.length > 0)
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        tos[0] = address(adv);
        // pick a nonzero value but let fuzzer choose via seed
        vals[0] = uint256(1) + (seed % 1000);

        // call transfer; the correct C uses call so adv's storage writes do not affect c.
        // try/catch used only to capture revert differences; here we expect success.
        bool ok;
        try c.transfer(attacker, address(adv), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: reference implementation never lets the callee change C's public uint "transfer" getter.
        // We assert that c.transfer() equals zero (the deployed C has default zero unless mutated by delegatecall in mutant).
        // This single assertion is true for the correct contract for all inputs, but a mutant using delegatecall can make it false for some inputs.
        assertTrue(c.transfer() == 0);
    }
}

// Adversarial callee: implements transferFrom(address,address,uint256)
// It writes to its own storage slot 0 (named transfer) when invoked.
// If C uses call, this write affects the callee only; if C mistakenly uses delegatecall, this write affects C's storage.
contract Adversary {
    // mirror the storage slot name 'transfer' to ensure same slot layout
    uint256 public transfer;

    // function signature matches bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) public returns (bool) {
        // write to storage slot 0
        transfer = v;
        return true;
    }
}

