pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the array length and a dummy value; the important deciding factor is that _tos is non-empty
    // and we route the caddress through a helper that returns success on being called.
    function testFuzz_property(uint8 len, uint256 dummy) public {
        // keep length reasonably bounded but allow zero too (we'll assume non-empty for the property)
        uint256 _len = bound(len, 0, 10);
        // must have at least one entry to exercise the loop; the universal property is about all inputs,
        // so we assert behavior only when _tos.length > 0 (the function itself requires that).
        vm.assume(_len > 0);

        // build arrays
        address[] memory tos = new address[](_len);
        uint[] memory vals = new uint[](_len);
        for (uint i = 0; i < _len; i++) {
            // all entries point to a helper that returns success when called
            ReturningCallee helper = new ReturningCallee();
            tos[i] = address(helper);
            vals[i] = dummy + i;
        }

        // call transfer; capture whether it returns (ok = true) or reverts (ok = false)
        bool ok;
        try c.transfer(address(1), address(2), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always completes (does not revert) for any non-empty _tos when
        // the callee returns success on its low-level call; the mutant inverts the check and will revert
        // for this scenario. Thus assertTrue(ok) is universally true for the reference and will fail on the mutant
        assertTrue(ok);
    }
}

// adversarial helper: models an external callee whose low-level call (transferFrom) succeeds
contract ReturningCallee {
    // accept any calldata and simply return true (no revert)
    fallback() external payable {
        // do nothing, low-level call will succeed and return empty success; caller interprets this as success
    }
}
